## 2. 知识图谱完整 Schema

知识图谱存储在 `.understand-anything/knowledge-graph.json`，是整个系统的数据核心。

### 2.1 顶层结构

```typescript
interface KnowledgeGraph {
  version: string;              // Schema 版本，用于迁移
  generatedAt: string;          // ISO 8601 时间戳
  projectName: string;          // 项目名称
  projectRoot: string;          // 项目根路径（绝对路径）

  nodes: KnowledgeNode[];       // 所有节点
  edges: KnowledgeEdge[];       // 所有关系边
  tours: GuidedTour[];          // 导览序列

  metadata: GraphMetadata;      // 图的统计元数据
  incrementalState: IncrementalState; // 增量分析状态
}
```

### 2.2 节点 Schema（KnowledgeNode）

```typescript
interface KnowledgeNode {
  // ── 标识 ──────────────────────────────────────────────
  id: string;          // 全局唯一 ID，格式: "filePath::symbolName"
  type: NodeType;      // 节点类型（见下方枚举）

  // ── 基本属性 ─────────────────────────────────────────
  name: string;        // 符号名（函数名/类名/文件名）
  file: string;        // 所在文件相对路径
  lineStart?: number;  // 起始行号
  lineEnd?: number;    // 结束行号

  // ── 语义标注（LLM 生成）──────────────────────────────
  summary: string;     // 平英摘要（1-3 句话）
  code?: string;       // 源码片段（函数签名或关键代码）

  // ── 架构标注（architecture-analyzer 填充）──────────
  layer: ArchitectureLayer;  // API | Service | Data | UI | Utility | Config

  // ── 语言概念标注 ──────────────────────────────────
  languageConcepts?: LanguageConcept[];
  // 枚举: generics | closures | decorators | async/await | 
  //       higher-order-functions | pattern-matching | 
  //       type-guards | mixins | currying | monads | 
  //       dependency-injection | observer-pattern

  // ── v2.0 扩展：非代码文件属性 ─────────────────────
  fileType?: "source" | "config" | "schema" | "infra" | "doc";
  rawContent?: string;  // 非代码文件的原始内容摘要

  // ── 搜索优化 ──────────────────────────────────────
  searchTokens?: string[];  // 预分词，加速 Fuse.js
}

type NodeType = 
  | "file" | "function" | "class" | "component"  // 代码
  | "config" | "document"                          // 文档/配置
  | "service" | "table" | "endpoint"              // 基础设施
  | "pipeline" | "schema" | "resource"            // CI/IaC
  | "domain" | "flow" | "step";                   // v2.1 域节点

type ArchitectureLayer =
  | "API" | "Service" | "Data" | "UI" | "Utility" | "Config" | "Unknown";
```

### 2.3 边 Schema（KnowledgeEdge）

```typescript
interface KnowledgeEdge {
  id: string;          // 自动生成: "${source}→${target}:${type}"
  source: string;      // 源节点 ID
  target: string;      // 目标节点 ID
  type: EdgeType;      // 关系类型
  weight?: number;     // 关系强度（0-1，未来用于搜索排序）
  metadata?: Record<string, unknown>;  // 扩展元数据
}
```

### 2.4 导览 Schema（GuidedTour）

```typescript
interface GuidedTour {
  id: string;
  title: string;
  description: string;
  persona: "all" | "developer" | "pm" | "newcomer";
  estimatedTime: string;  // "10 min" | "30 min"
  stops: TourStop[];
}

interface TourStop {
  nodeId: string;      // 对应图中的节点 ID
  order: number;       // 停止序号（1-based）
  narrative: string;   // LLM 生成的叙事性解释
  duration: string;    // 建议停留时间
  highlights?: string[]; // 重点关注的代码片段
}
```

### 2.5 Domain Graph Schema（v2.1）

```typescript
interface DomainGraph {
  version: string;
  generatedAt: string;

  nodes: DomainNode[];  // domain | flow | step 节点
  edges: DomainEdge[];  // contains | flows_to | implements 边
}

interface DomainNode {
  id: string;
  type: "domain" | "flow" | "step";
  name: string;
  description: string;

  // 关联到 architecture graph 的节点
  codeRefs?: string[];  // 对应的 KnowledgeNode.id 列表
}
```

