## 4. Persistence 层

### 4.1 存储策略

```typescript
class GraphPersistence {
  private readonly basePath = ".understand-anything";

  // 主图持久化
  async saveKnowledgeGraph(graph: KnowledgeGraph): Promise<void> {
    await fs.writeFile(
      path.join(this.basePath, "knowledge-graph.json"),
      JSON.stringify(graph, null, 2),
      "utf-8"
    );
  }

  // 增量状态持久化（记录已分析文件的 hash）
  async saveIncrementalState(state: IncrementalState): Promise<void> {
    await fs.writeFile(
      path.join(this.basePath, "incremental-state.json"),
      JSON.stringify(state),
      "utf-8"
    );
  }

  // 中间结果（Agent 间通信）
  async saveIntermediate(agentName: string, data: unknown): Promise<void> {
    await fs.writeFile(
      path.join(this.basePath, "intermediate", `${agentName}.json`),
      JSON.stringify(data)
    );
  }

  // 加载时 Zod 验证
  async loadKnowledgeGraph(): Promise<KnowledgeGraph | null> {
    const raw = await fs.readFile(/* ... */);
    return KnowledgeGraphSchema.parse(JSON.parse(raw));  // Zod 验证
  }
}
```

### 4.2 增量分析机制

```typescript
interface IncrementalState {
  version: string;
  analyzedFiles: Record<string, FileAnalysisState>;
}

interface FileAnalysisState {
  path: string;
  hash: string;          // SHA-256 of file content
  analyzedAt: string;    // ISO 8601
  nodeIds: string[];     // 此文件产生的所有节点 ID
  edgeIds: string[];     // 此文件产生的所有边 ID
}

// 增量分析逻辑
async function computeChangedFiles(
  currentFiles: FileInfo[],
  state: IncrementalState
): Promise<{ changed: FileInfo[]; deleted: string[] }> {
  const changed = currentFiles.filter(f => {
    const prev = state.analyzedFiles[f.path];
    return !prev || prev.hash !== computeHash(f.content);
  });

  const currentPaths = new Set(currentFiles.map(f => f.path));
  const deleted = Object.keys(state.analyzedFiles)
    .filter(p => !currentPaths.has(p));

  return { changed, deleted };
}
```

