## 7. Zod Schema 验证层

所有跨 Agent 的数据交换都通过 Zod Schema 验证，防止 LLM 输出的不规范数据污染图结构：

```typescript
import { z } from "zod";

const KnowledgeNodeSchema = z.object({
  id: z.string().min(1),
  type: z.enum(["file","function","class","component","config","document",
                 "service","table","endpoint","pipeline","schema","resource",
                 "domain","flow","step"]),
  name: z.string().min(1),
  file: z.string(),
  summary: z.string().default(""),
  layer: z.enum(["API","Service","Data","UI","Utility","Config","Unknown"])
          .default("Unknown"),
  lineStart: z.number().int().positive().optional(),
  lineEnd: z.number().int().positive().optional(),
  languageConcepts: z.array(z.string()).optional(),
});

const KnowledgeEdgeSchema = z.object({
  source: z.string(),
  target: z.string(),
  type: z.enum([/* EdgeType 枚举 */]),
}).refine(e => e.source !== e.target, { message: "Self-loops not allowed" });

// 从 LLM 输出解析，自动修复/丢弃非法数据
const parseAgentOutput = (raw: unknown) =>
  KnowledgeNodeSchema.array().safeParse(raw);
```

